#pragma once

// Which of the warnings OrcaSlicer stores on a slice result JusPrin shows: the
// bed-temperature, nozzle-hardness and timelapse checks the G-code processor
// runs after a slice (GCodeProcessorResult::warnings). The print-issue chip and
// slice_report both read this rule, so the person and the agent are told the
// same warnings.
//
// Which slice-result warnings JusPrin shows follows OrcaSlicer's send dialog
// (SelectMachineDialog, the loop over plate->get_slice_result()->warnings):
// the only place OrcaSlicer itself shows them. That rule is an if/else inside
// the dialog, not a list we can call. Making it callable would mean moving
// upstream lines in SelectMachine.cpp, which changes often upstream (about 367
// commits since 2025) and conflicts at rebase, so we copy the rule here
// instead. The guard test fails when OrcaSlicer adds a warning kind, so every
// new kind gets classified. It does not notice if OrcaSlicer changes its
// show/hide choice for an existing kind; whoever rebases a change to that loop
// must update this table. Accepted 2026-10-28. Known effect: OrcaSlicer shows
// these warnings only in its Bambu send dialogs, so for other printers
// OrcaSlicer shows none of them, and this table does not try to do better.

#include <cstddef>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Workspace {

enum class SliceResultWarningShown {
    Always,
    // Only for a print that records a timelapse, which is chosen when the
    // print is sent; the chip does not count it before then.
    WhenRecordingTimelapse,
    Never,
};

struct SliceResultWarningRule
{
    // OrcaSlicer's id for the kind: one of the slice warning constants in
    // libslic3r/GCode/GCodeProcessor.hpp, never its display text.
    std::string             kind;
    SliceResultWarningShown shown;
    // OrcaSlicer stores some kinds twice under two error codes with the same
    // words; the send dialog shows them once.
    bool                    once;
};

// Every kind OrcaSlicer defines, each classified once.
const std::vector<SliceResultWarningRule>& slice_result_warning_rules();

// What OrcaSlicer's send dialog does with a warning of `kind`. A kind the
// table does not name, which a file from a newer OrcaSlicer could carry, is
// not shown, as the send dialog does not show it.
SliceResultWarningShown slice_result_warning_shown(const std::string& kind);

// Of a result's warnings, given by kind in OrcaSlicer's order, the positions
// of the ones shown: Never kinds left out, a `once` kind kept the first time.
std::vector<std::size_t> shown_slice_result_warnings(const std::vector<std::string>& kinds);

} // namespace Slic3r::GUI::JusPrin::Workspace

#include "SliceResultWarnings.hpp"

#include "libslic3r/GCode/GCodeProcessor.hpp"

#include <algorithm>

namespace Slic3r::GUI::JusPrin::Workspace {

const std::vector<SliceResultWarningRule>& slice_result_warning_rules()
{
    using Shown = SliceResultWarningShown;
    static const std::vector<SliceResultWarningRule> rules{
        {NOZZLE_HRC_CHECKER, Shown::Always, false},
        // Shown only while the dialog's timelapse box is ticked, and once
        // although the processor stores it as 10018003 and again as 1000C003
        // for older A-series firmware.
        {NOT_SUPPORT_TRADITIONAL_TIMELAPSE, Shown::WhenRecordingTimelapse, true},
        {SMOOTH_TIMELAPSE_WITHOUT_PRIME_TOWER, Shown::WhenRecordingTimelapse, false},
        // The dialog skips it; its status line says the same in other words.
        {NOT_GENERATE_TIMELAPSE, Shown::Never, false},
        // The dialog never names it.
        {BED_TEMP_TOO_HIGH_THAN_FILAMENT, Shown::Never, false},
        // Nothing raises it, and OrcaSlicer has no words for it.
        {LONG_RETRACTION_WHEN_CUT, Shown::Never, false},
    };
    return rules;
}

SliceResultWarningShown slice_result_warning_shown(const std::string& kind)
{
    const auto& rules = slice_result_warning_rules();
    const auto  found = std::find_if(rules.begin(), rules.end(), [&kind](const SliceResultWarningRule& rule) { return rule.kind == kind; });
    return found == rules.end() ? SliceResultWarningShown::Never : found->shown;
}

std::vector<std::size_t> shown_slice_result_warnings(const std::vector<std::string>& kinds)
{
    const auto&              rules = slice_result_warning_rules();
    std::vector<std::size_t> shown;
    for (std::size_t index = 0; index < kinds.size(); ++index) {
        const auto rule = std::find_if(rules.begin(), rules.end(),
                                       [&](const SliceResultWarningRule& candidate) { return candidate.kind == kinds[index]; });
        if (rule == rules.end() || rule->shown == SliceResultWarningShown::Never)
            continue;
        if (rule->once && std::any_of(shown.begin(), shown.end(), [&](std::size_t earlier) { return kinds[earlier] == kinds[index]; }))
            continue;
        shown.push_back(index);
    }
    return shown;
}

} // namespace Slic3r::GUI::JusPrin::Workspace

// Which slice-result warnings JusPrin shows: OrcaSlicer's send-dialog rule,
// copied into SliceResultWarnings. Linked against libslic3r, because the
// kinds are OrcaSlicer's.

#include <catch2/catch_all.hpp>

#include "libslic3r/GCode/GCodeProcessor.hpp"
#include "slic3r/GUI/JusPrin/Workspace/SliceResultWarnings.hpp"

#include <fstream>
#include <regex>
#include <set>
#include <string>

using namespace Slic3r::GUI::JusPrin::Workspace;

namespace {

// The ids in GCodeProcessor.hpp's block of slice warning constants, read
// from the file so a constant OrcaSlicer adds is seen without a code change.
std::set<std::string> defined_kinds()
{
    std::ifstream header(std::string(JUSPRIN_SOURCE_DIR) + "/src/libslic3r/GCode/GCodeProcessor.hpp");
    REQUIRE(header.good());
    const std::regex      define(R"(^\s*#define\s+\w+\s+"([^"]+)\"\s*$)");
    std::set<std::string> kinds;
    bool                  in_block = false;
    for (std::string line; std::getline(header, line);) {
        if (line.find("slice warnings enum strings") != std::string::npos) {
            in_block = true;
            continue;
        }
        std::smatch match;
        if (in_block && std::regex_match(line, match, define))
            kinds.insert(match[1]);
        else if (in_block && !kinds.empty())
            break;
    }
    return kinds;
}

} // namespace

TEST_CASE("every slice warning kind OrcaSlicer defines is classified", "[slice-warnings]")
{
    const std::set<std::string> defined = defined_kinds();
    REQUIRE(defined.size() >= 6);
    std::set<std::string> classified;
    for (const SliceResultWarningRule& rule : slice_result_warning_rules()) {
        CAPTURE(rule.kind);
        CHECK(classified.insert(rule.kind).second);
        CHECK(defined.count(rule.kind) == 1);
    }
    // A kind OrcaSlicer added: copy its choice from SelectMachineDialog's
    // loop over the slice result's warnings into the table.
    for (const std::string& kind : defined) {
        CAPTURE(kind);
        CHECK(classified.count(kind) == 1);
    }
}

TEST_CASE("the send dialog's choices", "[slice-warnings]")
{
    CHECK(slice_result_warning_shown(NOZZLE_HRC_CHECKER) == SliceResultWarningShown::Always);
    CHECK(slice_result_warning_shown(NOT_SUPPORT_TRADITIONAL_TIMELAPSE) == SliceResultWarningShown::WhenRecordingTimelapse);
    CHECK(slice_result_warning_shown(SMOOTH_TIMELAPSE_WITHOUT_PRIME_TOWER) == SliceResultWarningShown::WhenRecordingTimelapse);
    CHECK(slice_result_warning_shown(NOT_GENERATE_TIMELAPSE) == SliceResultWarningShown::Never);
    CHECK(slice_result_warning_shown(BED_TEMP_TOO_HIGH_THAN_FILAMENT) == SliceResultWarningShown::Never);
    CHECK(slice_result_warning_shown(LONG_RETRACTION_WHEN_CUT) == SliceResultWarningShown::Never);
    // A file from a newer OrcaSlicer can carry a kind this one does not know.
    CHECK(slice_result_warning_shown("a_kind_from_a_newer_orcaslicer") == SliceResultWarningShown::Never);
}

TEST_CASE("a result's warnings as shown", "[slice-warnings]")
{
    // The hook on its side with supports, on an A1 mini: bed temperature,
    // then the traditional-timelapse warning stored twice (10018003, 1000C003).
    CHECK(shown_slice_result_warnings({BED_TEMP_TOO_HIGH_THAN_FILAMENT, NOT_SUPPORT_TRADITIONAL_TIMELAPSE,
                                       NOT_SUPPORT_TRADITIONAL_TIMELAPSE}) == std::vector<std::size_t>{1});
    CHECK(shown_slice_result_warnings({BED_TEMP_TOO_HIGH_THAN_FILAMENT}).empty());
    CHECK(shown_slice_result_warnings({NOZZLE_HRC_CHECKER, SMOOTH_TIMELAPSE_WITHOUT_PRIME_TOWER, NOT_GENERATE_TIMELAPSE}) ==
          std::vector<std::size_t>{0, 1});
    CHECK(shown_slice_result_warnings({}).empty());
}

